import{_ as a,c as n,o as r,j as o,Y as s,t as i}from"./chunks/framework.BNTND4LZ.js";const u=JSON.parse('{"title":"networks | x-cmd man (man5) | network name information","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | networks - network name information","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"networks | x-cmd man (man5) | network name information"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | networks - network name information"}]]},"headers":[],"params":{"isMan":true,"man":"networks","category":"man5","desc":"network name information"},"relativePath":"man5/networks.md","filePath":"man5/[man].md"}'),d={name:"man5/networks.md"},m={class:"visually-hidden"};function l(t,e,c,h,p,f){return r(),n("div",null,[o("h1",m,i(t.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>networks - network name information</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The file <em>/etc/networks</em> is a plain ASCII file that describes known DARPA networks and symbolic names for these networks. Each line represents a network and has the following structure:</p><blockquote><p><em>name number aliases ...</em></p></blockquote><p>where the fields are delimited by spaces or tabs. Empty lines are ignored. The hash character (<strong>#</strong>) indicates the start of a comment: this character, and the remaining characters up to the end of the current line, are ignored by library functions that process the file.</p><p>The field descriptions are:</p><dl><dt><em>name</em></dt><dd>The symbolic name for the network. Network names can contain any printable characters except white-space characters or the comment character.</dd><dt><em>number</em></dt><dd>The official number for this network in numbers-and-dots notation (see <strong>inet</strong>(3)). The trailing &quot;.0&quot; (for the host component of the network address) may be omitted.</dd><dt><em>aliases</em></dt><dd>Optional aliases for the network.</dd></dl><p>This file is read by the <strong>route</strong>(8) and <strong>netstat</strong>(8) utilities. Only Class A, B, or C networks are supported, partitioned networks (i.e., network/26 or network/28) are not supported by this file.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt><em>/etc/networks</em></dt><dd>The networks definition file.</dd></dl><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>getnetbyaddr</strong>(3), <strong>getnetbyname</strong>(3), <strong>getnetent</strong>(3), <strong>netstat</strong>(8), <strong>route</strong>(8)</p>',13))])}const g=a(d,[["render",l]]);export{u as __pageData,g as default};
